export const BAR_TEMPLATE: string = "\"$schema\" = 'https://starship.rs/config-schema.json'\n\n# Claude Code status bar rendered by Starship, laid out like the oh-my-posh one.\n# The binary packs the visible segments of each line into numbered slots\n# (CC_L<line>_<slot>) and sets one CC_L<line>_END<n> for the last slot used, so\n# the rounded end cap always takes that slot's color.\n# Glyphs are written as \\u escapes: U+E0B6 start cap, U+E0B0 arrow, U+E0B4 end\n# cap, U+F07B folder. Keep them escaped; raw Nerd Font glyphs get lost in edits.\nadd_newline = false\npalette = '{{THEME}}'\n\nformat = \"\"\"\n[\\ue0b6](fg:l1_1)\\\n${env_var.CC_L1_1}${env_var.CC_L1_2}${env_var.CC_L1_3}${env_var.CC_L1_4}\\\n${env_var.CC_L1_END1}${env_var.CC_L1_END2}${env_var.CC_L1_END3}${env_var.CC_L1_END4}\\\n$line_break\\\n[\\ue0b6](fg:l2_1)$directory${env_var.CC_L2_2}${env_var.CC_L2_3}\\\n${env_var.CC_L2_END1}${env_var.CC_L2_END2}${env_var.CC_L2_END3}\\\n$line_break\\\n[\\ue0b6](fg:l3_1)\\\n${env_var.CC_L3_1}${env_var.CC_L3_2}${env_var.CC_L3_3}${env_var.CC_L3_4}\\\n${env_var.CC_L3_END1}${env_var.CC_L3_END2}${env_var.CC_L3_END3}${env_var.CC_L3_END4}\"\"\"\n\n{{PALETTE}}\n\n# Line 1: model, effort, version, account\n[env_var.CC_L1_1]\nformat = \"[ $env_value ](fg:f1_1 bg:l1_1)\"\n\n[env_var.CC_L1_2]\nformat = \"[\\ue0b0](fg:l1_1 bg:l1_2)[ $env_value ](fg:f1_2 bg:l1_2)\"\n\n[env_var.CC_L1_3]\nformat = \"[\\ue0b0](fg:l1_2 bg:l1_3)[ $env_value ](fg:f1_3 bg:l1_3)\"\n\n[env_var.CC_L1_4]\nformat = \"[\\ue0b0](fg:l1_3 bg:l1_4)[ $env_value ](fg:f1_4 bg:l1_4)\"\n\n[env_var.CC_L1_END1]\nformat = \"[\\ue0b4](fg:l1_1)\"\n\n[env_var.CC_L1_END2]\nformat = \"[\\ue0b4](fg:l1_2)\"\n\n[env_var.CC_L1_END3]\nformat = \"[\\ue0b4](fg:l1_3)\"\n\n[env_var.CC_L1_END4]\nformat = \"[\\ue0b4](fg:l1_4)\"\n\n# Line 2: directory, branch or worktree, lines changed and session time\n[directory]\nformat = \"[ \\uf07b $path ](fg:f2_1 bg:l2_1)[$read_only](fg:f2_1 bg:l2_1)\"\ntruncation_length = 3\ntruncate_to_repo = false\ntruncation_symbol = '…/'\n\n[env_var.CC_L2_2]\nformat = \"[\\ue0b0](fg:l2_1 bg:l2_2)[ $env_value ](fg:f2_2 bg:l2_2)\"\n\n[env_var.CC_L2_3]\nformat = \"[\\ue0b0](fg:l2_2 bg:l2_3)[ $env_value ](fg:f2_3 bg:l2_3)\"\n\n[env_var.CC_L2_END1]\nformat = \"[\\ue0b4](fg:l2_1)\"\n\n[env_var.CC_L2_END2]\nformat = \"[\\ue0b4](fg:l2_2)\"\n\n[env_var.CC_L2_END3]\nformat = \"[\\ue0b4](fg:l2_3)\"\n\n# Line 3: context, prompt cache timer, 5h and 7d rate limits\n[env_var.CC_L3_1]\nformat = \"[ $env_value ](fg:f3_1 bg:l3_1)\"\n\n[env_var.CC_L3_2]\nformat = \"[\\ue0b0](fg:l3_1 bg:l3_2)[ $env_value ](fg:f3_2 bg:l3_2)\"\n\n[env_var.CC_L3_3]\nformat = \"[\\ue0b0](fg:l3_2 bg:l3_3)[ $env_value ](fg:f3_3 bg:l3_3)\"\n\n[env_var.CC_L3_4]\nformat = \"[\\ue0b0](fg:l3_3 bg:l3_4)[ $env_value ](fg:f3_4 bg:l3_4)\"\n\n[env_var.CC_L3_END1]\nformat = \"[\\ue0b4](fg:l3_1)\"\n\n[env_var.CC_L3_END2]\nformat = \"[\\ue0b4](fg:l3_2)\"\n\n[env_var.CC_L3_END3]\nformat = \"[\\ue0b4](fg:l3_3)\"\n\n[env_var.CC_L3_END4]\nformat = \"[\\ue0b4](fg:l3_4)\"\n";

